function objectivePanel(){const objs=d.objectives||[],teams=d.summary?.teams||[];return '<div class="panel exec-section"><div class="exec-section-head"><div><h3>Objetivos mensuales de Dirección</h3><p>El OBJ es único para todo el mes. Arranque, semanas y PreCierre se comparan contra el mismo valor. Si no existe un OBJ manual, Sfera usa el PPTO mensual.</p></div><button class="action" id="setObjective">Cambiar objetivo mensual</button></div><div class="objective-grid">'+teams.map(t=>{const own=objs.find(x=>(x.teamId||"")===t.teamId),national=objs.find(x=>!x.teamId),o=own||national,v=objectiveForSummary(t),gap=num(t.forecast)-v,pct=v?Math.max(0,Math.min(100,num(t.forecast)/v*100)):0,cls=gap>=0?"positive":"negative";return '<div class="objective-card"><div class="objective-top"><strong>'+esc(t.teamId)+'</strong><span class="objective-gap '+cls+'">'+(gap>=0?"+":"")+money(gap)+'</span></div><div class="objective-values"><div><span>Forecast '+esc(stageHuman(d.stage||"ARR"))+'</span><b>'+money(t.forecast)+'</b></div><div><span>OBJ mensual</span><b>'+money(v)+'</b></div></div><div class="muted" style="margin:5px 0">'+(o&&o.manual?"Objetivo mensual manual":"PPTO mensual por defecto")+'</div><div class="progress"><span style="width:'+pct+'%"></span></div></div>'}).join("")+'</div></div>'}
