 const all=wb2Data_(d.workbenchHierarchy,"").rows,r=all.find(x=>x.key===key);if(!r)return showNotice("La línea ya no está disponible con este acceso.");
 const present=wb2Select_(wb2Data_(d.workbenchHierarchy,workbenchClientFilter).rows).some(x=>x.key===key);
 if(!present){if(!wb2.returnContext)wb2.returnContext={exec:wb2.exec,medium:wb2.medium,holding:wb2.holding,agency:wb2.agency,missing:wb2.missing,q:workbenchClientFilter,page:wb2.page};Object.assign(wb2,{exec:r.executiveId,medium:"",holding:"",agency:"",missing:false});workbenchClientFilter=r.raw;const input=qs("#workbenchClientFilter");if(input)input.value=workbenchClientFilter;}
