async function wb2ImportOne_(r){
 if(submitInFlight||contextChanging||!d.stageEditable)return showNotice("La etapa no permite importar Dato Real.");
 const source=workingIndex.get(r.key);if(!source)return showNotice("La línea ya no está disponible.");
 const period=d.period,stage=d.stage,originalRevision=workingRevision.get(r.key)||0;
 const line={rowKeys:[r.key],clientReal:r.raw,medium:r.medium,holding:r.holding,real:num(source.real??r.real),fc:num(source.fc),py:num(source.py),pa:num(source.pa),pl:num(source.pl)};
 const raw={rawName:r.raw,lines:[line]};
 if(Math.abs(num(source.fc)-num(line.real))<.5)return showNotice("Dato Forecast y Dato Real ya coinciden en la línea seleccionada.");
 const decision=await wbImportDecision_(raw,wbImportPreview_(raw));
 if(!decision||period!==d.period||stage!==d.stage||!d.stageEditable||!workingIndex.has(r.key))return;
 const totals=wbImportTotals_(decision.lines),delta=totals.next-totals.before;
 if(delta>0){const accepted=await openSferaConfirm({title:"Confirmar aumento del Forecast",subtitle:r.raw+" · "+r.medium+" · "+r.executive,confirmLabel:"Sí, aumentar Forecast",html:'<div class="confirm-metrics"><div><span>Forecast anterior</span><b>'+money(totals.before)+'</b></div><div><span>Forecast siguiente</span><b>'+money(totals.next)+'</b></div><div><span>Aumento</span><b>'+signedMoney(delta)+'</b></div></div>'});if(!accepted)return;}
 if(period!==d.period||stage!==d.stage||!d.stageEditable||!workingIndex.has(r.key)||(workingRevision.get(r.key)||0)!==originalRevision)return showNotice("La línea cambió durante la confirmación; consulta sus valores antes de importar.");
 decision.lines.forEach(item=>["fc","py","pa","pl"].forEach(field=>wbApplyValue_([r.key],field,num(item[field]))));
 scheduleAutosave_(1000);updateDirtyBanner_();wb2SyncAfterImport_();
 showNotice("Real importado únicamente en "+r.medium+" · "+r.executive+" · "+r.key.slice(0,10)+". Cambios pendientes de guardar.");
}
function wb2SourceAction_(key,kind,group){
 const rows=wb2GroupRows_(group),r=rows.find(x=>x.key===key);
 if(!r||!d.stageEditable)return showNotice("Origen no autorizado o etapa cerrada.");
 wb2.picker=null;
 if(kind.startsWith("create:"))return addLineFromRaw_(r.ei,r.ci,r.ri,r.key,{medium:kind.slice(7),group});
 if(kind==="add")return addLineFromRaw_(r.ei,r.ci,r.ri,r.key);
 if(kind==="import")return wb2ImportOne_(r);
 if(kind==="neg")return negEditFromWorkbench_(r.key);
}

