  const input=e.target;if(!input.matches(".wb2-shell input[data-wb2-delta]"))return;
  e.stopImmediatePropagation();e.preventDefault();
  const id=input.dataset.wb2Delta,td=input.closest("td[data-wb2-f]"),group=td?.closest("tr")?.dataset.wb2Group;
  const all=wb2Data_(d.workbenchHierarchy,"").rows,field=input.dataset.field,medium=td?.dataset.wb2M||"",rows=all.filter(r=>wb2GroupKey_(r)===group&&(!medium||wb2Medium_(r.medium)===medium));
  let edit=wb2.deltaEdits.get(id);
