 if(!hard)html+='<button class="action primary" id="confirmSourceUpload">'+(warnings?'Actualizar aceptando advertencias':'Procesar registros clasificados')+'</button>';qs("#sourcePreview").innerHTML=html;const btn=qs("#confirmSourceUpload");if(btn)btn.onclick=confirmPreparedSource;
