function negBoardFiltersHtml_(h,real){
 const selectors=[["teamId","Equipo"],["clientId","Cliente Unificado"],["clientRealId","Cliente Real"],["executiveId","Ejecutivo"],["medium","Medio"],["negotiationId","Negociación"]];
 const active=selectors.some(x=>Boolean(assocSelections[x[0]==="negotiationId"?"negotiation":x[0]]?.length));
 if(!negBoardCatalog||negBoardCatalog.period!==d.period||!active){
  const all=[...(h.lines||[]),...(real.lines||[])],unique=(key,label)=>[...new Map(all.map(x=>[String(x[key]||""),String(x[label]||x[key]||"")]).filter(x=>x[0])).entries()].map(([value,text])=>({value,text})).sort((a,b)=>a.text.localeCompare(b.text));
  negBoardCatalog={period:d.period,teamId:unique("teamId","teamId"),clientId:unique("clientId","client"),clientRealId:unique("clientRealId","rawClient"),executiveId:unique("executiveId","executive"),medium:unique("medium","medium"),negotiationId:(h.labels||[]).map(x=>({value:x.id,text:x.name}))};
 }
 const make=(key,title)=>'<label>'+esc(title)+'<select data-neg-filter="'+key+'"><option value="">Todos</option>'+(negBoardCatalog[key]||[]).map(x=>'<option value="'+esc(x.value)+'"'+((assocSelections[key==="negotiationId"?"negotiation":key]||[]).some(v=>assocCanonicalValue_(key,v)===assocCanonicalValue_(key,x.value))?' selected':'')+'>'+esc(x.text)+'</option>').join("")+'</select></label>';
 const stages=(d.availableStages||[]).map(x=>typeof x==="string"?x:String(x.stage||x.id||"")).filter(Boolean);
 return '<div class="neg-filters">'+selectors.map(x=>make(x[0],x[1])).join("")+'<label>Etapa histórica<select data-neg-filter="stage"><option value="">Etapa actual</option>'+stages.map(x=>'<option value="'+esc(x)+'"'+(negBoardFilters.stage===x?' selected':'')+'>'+esc(x)+'</option>').join("")+'</select></label><button class="action" id="negClearFilters">Limpiar filtros</button></div>';
}
function negBindBoardFilters_(){
 document.querySelectorAll("[data-neg-filter]").forEach(el=>el.onchange=()=>{const key=el.dataset.negFilter;if(key==="stage"){changeTopContext_(d.period,el.value||d.stage);return;}assocSetSingle_(key==="negotiationId"?"negotiation":key,el.value);});
 const clear=qs("#negClearFilters");if(clear)clear.onclick=()=>{const before=assocFingerprint_(),draft=JSON.parse(before);["teamId","clientId","clientRealId","executiveId","medium","negotiation"].forEach(k=>delete draft[k]);if(JSON.stringify(draft)===before)return;assocUndo.push(before);assocRedo=[];assocSelections=draft;assocApply_();};
}
function negBoardView_(target){const h=d.negHistory||{},real=d.negReal||{},rows=h.lines||[],totals=real.totals||{},forecast=rows.reduce((n,r)=>n+num(r.forecast),0),assigned=rows.reduce((n,r)=>n+(r.assignments||[]).reduce((a,x)=>a+num(x.amount),0),0);
 target.innerHTML='<div class="panel analysis-shell">'+negBoardFiltersHtml_(h,real)+'<div class="analysis-head"><div><h2>Cuadro de Mando · Negociaciones</h2><p>Forecast histórico de etapa '+esc(h.stage||d.stage)+' · Real del último corte oficial '+esc(real.cutAt||"no disponible")+'</p></div></div>'+negStats_([["Forecast de etapa",forecast],["Forecast negociaciones",assigned],["Forecast Normal",forecast-assigned],["Real oficial",totals.total],["Real con negociación",totals.assigned],["Real sin negociación confirmado",totals.confirmedNormal],["Real pendiente",totals.pending],["Forecast menos Real",forecast-num(totals.total)]])+'<p class="muted">Real: '+money(totals.assigned)+' + '+money(totals.confirmedNormal)+' + '+money(totals.pending)+' = '+money(totals.total)+' · '+num(totals.conflicts)+' conflictos</p>'+negTable_(rows,h.labels,true)+'<h3>Evolución por etapa</h3><div class="tablewrap"><table><thead><tr><th>Etapa</th><th>Forecast</th><th>Negociaciones</th><th>Normal</th></tr></thead><tbody>'+(h.evolution||[]).map(x=>'<tr><td>'+esc(x.stage)+'</td><td>'+money(x.forecast)+'</td><td>'+money(x.assigned)+'</td><td>'+money(x.normal)+'</td></tr>').join("")+'</tbody></table></div><h3>Participación por negociación</h3>'+negParticipationHtml_(rows,real,h.labels||[])+'</div>';negBindBoardFilters_();}


function negParticipationHtml_(forecastRows,real,labels){
 const agg=new Map(labels.map(x=>[String(x.id),{name:x.name,forecast:0,real:0}]));
 (forecastRows||[]).forEach(row=>(row.assignments||[]).forEach(a=>{if(!agg.has(String(a.negotiationId)))agg.set(String(a.negotiationId),{name:a.negotiationId,forecast:0,real:0});agg.get(String(a.negotiationId)).forecast+=num(a.amount);}));
 (real.lines||[]).forEach(row=>(row.assignments||[]).forEach(a=>{if(!agg.has(String(a.negotiationId)))agg.set(String(a.negotiationId),{name:a.negotiationId,forecast:0,real:0});agg.get(String(a.negotiationId)).real+=num(a.amount);}));
 const rows=[...agg.values()].filter(x=>x.forecast||x.real).sort((a,b)=>b.forecast-a.forecast),fc=rows.reduce((n,x)=>n+x.forecast,0),dr=rows.reduce((n,x)=>n+x.real,0);
 return '<div class="tablewrap"><table><thead><tr><th>Negociación</th><th>Forecast</th><th>Participación Forecast</th><th>Real confirmado</th><th>Participación Real</th></tr></thead><tbody>'+rows.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+money(x.forecast)+'</td><td>'+(fc?FMT_DEC1.format(x.forecast/fc*100):"0")+'%</td><td>'+money(x.real)+'</td><td>'+(dr?FMT_DEC1.format(x.real/dr*100):"0")+'%</td></tr>').join("")+'</tbody></table></div>';
}


const assocLabels={teamId:"Equipo",executiveId:"Ejecutivo",clientId:"Cliente unificado",clientRealId:"Cliente Real",agency:"Agencia",holding:"Holding",medium:"Medio",negotiation:"Negociación",clientType:"Tipo de cliente"};
const assocViews=new Set(["Cuadro Global","Cuadro Mensual","Cuadro de Ejecutivos","Cuadro de Agencias","Resumen","Resumen Nacional","Equipos","Clientes","Ejecutivos","Agencias","Histórico","Cuadro de Negociaciones","Negociaciones","Conciliación del Real","Pendientes","Alertas críticas","Mesa de trabajo"]);
let assocSelections={},assocUndo=[],assocRedo=[],assocAlternative={},assocResult=null,assocSequence=0,assocVersion=0,assocPanelOpen=false,assocSearch={};
let mesaOperationalPeriod="",assocAnalyticPeriod="";
function assocCanonicalValue_(key,value){const text=String(value||""),n=text.trim().toUpperCase();return key==="medium"?(n==="R"||n==="RADIO"?"Radio":n==="DIGITAL"?"Digital":text):text;}
function assocActive_(){return Object.keys(assocSelections).some(k=>assocSelections[k]?.length>0);}
function assocFingerprint_(){return JSON.stringify(assocSelections);}
function assocCompatible_(name){return assocViews.has(name||currentView);}
function assocAttributionNotice_(){const sources=currentView==="Cuadro Mensual"?d.monthly?.unattributableDimensions:(currentView==="Cuadro de Ejecutivos"||currentView==="Cuadro de Agencias")?d.dimensionDashboard?.unattributableDimensions:null;if(!sources)return "";const missing=Object.entries(sources).filter(([k,v])=>v?.length).map(([k,v])=>k+": "+v.map(x=>assocLabels[x]||x).join(", "));return missing.length?"Sin relación verificable; selección no aplicada a estas fuentes: "+missing.join(" · "):"";}
function assocRenderBar_(){
 const bar=qs("#assocToolbar");if(!bar)return;
 if(!assocCompatible_(currentView)){bar.innerHTML="";bar.hidden=true;return;}bar.hidden=false;
 const keys=Object.keys(assocSelections).filter(k=>assocSelections[k]?.length),count=keys.reduce((n,k)=>n+assocSelections[k].length,0);
 const chips=keys.map(key=>'<span class="assoc-chip">'+esc(assocLabels[key]||key)+': '+esc(assocSelections[key].slice(0,2).join(", "))+(assocSelections[key].length>2?" +"+(assocSelections[key].length-2):"")+'<button type="button" data-assoc-clear="'+esc(key)+'" aria-label="Quitar filtro '+esc(assocLabels[key]||key)+'">×</button></span>').join("");
 const selectionLabel=count?count+" valores seleccionados":"Todos los datos autorizados";
 bar.innerHTML='<div class="assoc-strip"><strong>Exploración asociativa</strong><span class="muted">'+esc(selectionLabel)+'</span>'+chips+'<div class="assoc-buttons"><button type="button" class="action" id="assocExpand" aria-expanded="'+assocPanelOpen+'">Filtros</button><button type="button" class="action" id="assocUndo" '+(assocUndo.length?'':'disabled')+'>Deshacer</button><button type="button" class="action" id="assocRedo" '+(assocRedo.length?'':'disabled')+'>Rehacer</button><button type="button" class="action" id="assocClear" '+(count?'':'disabled')+'>Limpiar todo</button><button type="button" class="action" id="assocPin">Fijar A</button><button type="button" class="action" id="assocUnpin" '+(assocAlternative?'':'disabled')+'>Quitar A</button></div></div>'+
 (assocPanelOpen?'<div class="assoc-panel">'+Object.keys(assocLabels).map(key=>{
 const facet=(assocResult?.facets?.[key]||[]),q=String(assocSearch[key]||"").toLocaleLowerCase(),shown=facet.filter(x=>!q||x.value.toLocaleLowerCase().includes(q)).slice(0,70),selected=new Set(assocSelections[key]||[]);
 return '<div class="assoc-field"><label><strong>'+esc(assocLabels[key])+'</strong><input type="search" data-assoc-search="'+esc(key)+'" placeholder="Buscar..." value="'+esc(assocSearch[key]||"")+'"></label><div class="assoc-options" role="group" aria-label="'+esc(assocLabels[key])+'">'+(shown.length?shown.map(o=>'<button type="button" class="assoc-option '+esc(o.state.toLowerCase().replace(/_/g,"-"))+'" data-assoc-key="'+esc(key)+'" data-assoc-val="'+esc(o.value)+'" aria-pressed="'+selected.has(o.value)+'"><span>'+esc(o.value==="__UNATTRIBUTABLE__"?"Sin atribución verificable":o.value)+'</span><small>'+esc(o.state.replace(/_/g," ").toLowerCase())+' · '+o.count+'</small></button>').join(""):'<div class="muted">Sin opciones o aún cargando.</div>')+'</div></div>'}).join("")+'</div>':'')+'<p class="muted" role="status">'+esc(assocAttributionNotice_())+'</p><div id="assocCompare" class="assoc-compare" role="status"></div>';
 bar.querySelectorAll("[data-assoc-clear]").forEach(b=>b.onclick=()=>assocChange_(b.dataset.assocClear,null,true));
 const e=qs("#assocExpand");if(e)e.onclick=()=>{assocPanelOpen=!assocPanelOpen;assocRenderBar_();if(assocPanelOpen&&!assocResult)assocRefresh_();};
 const clear=qs("#assocClear");if(clear)clear.onclick=()=>assocChange_(null,null,true);
 const pin=qs("#assocPin");if(pin)pin.onclick=()=>{assocAlternative=JSON.parse(assocFingerprint_());assocRenderBar_();};const unpin=qs("#assocUnpin");if(unpin)unpin.onclick=()=>{assocAlternative=null;assocRenderBar_();};
 const undo=qs("#assocUndo");if(undo)undo.onclick=()=>assocUndoRedo_("undo");
 const redo=qs("#assocRedo");if(redo)redo.onclick=()=>assocUndoRedo_("redo");
 bar.querySelectorAll("[data-assoc-key]").forEach(b=>b.onclick=()=>assocChange_(b.dataset.assocKey,b.dataset.assocVal,false));
 bar.querySelectorAll("[data-assoc-search]").forEach(input=>input.oninput=()=>{assocSearch[input.dataset.assocSearch]=input.value;const selectionStart=input.selectionStart;assocRenderBar_();const next=bar.querySelector('[data-assoc-search="'+input.dataset.assocSearch+'"]');if(next){next.focus();next.setSelectionRange(selectionStart,selectionStart);}});
 if(assocAlternative){const compare=qs("#assocCompare");if(compare)compare.textContent="Comparación A/B actualizando…";if(assocResult)assocCompareRefresh_();}
}
function assocChange_(key,value,clear){
 if(key&&value!=null)value=assocCanonicalValue_(key,value);
 const before=assocFingerprint_(),draft=JSON.parse(before);
 if(key&&clear)delete draft[key];else if(!key&&clear)Object.keys(draft).forEach(k=>delete draft[k]);else if(key&&value!==null){const values=new Set(draft[key]||[]);if(values.has(value))values.delete(value);else values.add(value);if(values.size)draft[key]=[...values];else delete draft[key];}
 if(JSON.stringify(draft)===before)return;assocUndo.push(before);if(assocUndo.length>35)assocUndo.shift();assocRedo=[];assocSelections=draft;assocApply_();
}
function assocUndoRedo_(direction){
 if(direction==="undo"&&!assocUndo.length||direction==="redo"&&!assocRedo.length)return;
 const from=direction==="undo"?assocUndo:assocRedo,to=direction==="undo"?assocRedo:assocUndo;
 to.push(assocFingerprint_());assocSelections=JSON.parse(from.pop());assocApply_();
}
function assocApply_(){
 assocVersion++;assocRenderBar_();
 if(!assocCompatible_(currentView))return;
 invalidateViews_(Array.from(assocViews).filter(x=>x!=="Mesa de trabajo"));
 if(currentView==="Mesa de trabajo"){renderWorkbenchClientFilter_();assocWorkbenchSelection_();assocRefresh_();return;}
 assocRefresh_();render(currentView);
}
async function assocRefresh_(){
 if(d.demo)return;const current=++assocSequence,period=d.period,stage=d.stage,version=assocVersion;
 try{const x=await gasGet("associations",{period,stage,assoc:assocFingerprint_()},false);
 if(current!==assocSequence||version!==assocVersion||period!==d.period||stage!==d.stage)return;
 if(x.ok){assocResult=x;assocRenderBar_();}else showNotice(x.error||"No se pudo calcular la asociación");
 }catch(e){if(current===assocSequence)showNotice("Error de exploración: "+(e.message||e));}
}
document.addEventListener("click",event=>{const button=event.target.closest("[data-assoc-pick]");if(!button)return;event.stopPropagation();assocSelect_(button.dataset.assocPick,button.dataset.assocValue);});
function assocSetSingle_(dimension,value){
 if(!dimension)return;const key=String(dimension),next=assocCanonicalValue_(key,value),before=assocFingerprint_(),draft=JSON.parse(before);
 if(next)draft[key]=[next];else delete draft[key];if(JSON.stringify(draft)===before)return;
 assocUndo.push(before);if(assocUndo.length>35)assocUndo.shift();assocRedo=[];assocSelections=draft;assocApply_();
}
function assocResolveFromLocal_(key,value){
 if(!value)return "";
 const facts=d.analytics?.facts||[],match=facts.find(x=>String(x[key])===String(value));
 if(key==="group")return match?.teamId||value;
 if(key==="executive")return match?.executiveId||value;
 return value;
}

async function assocCompareRefresh_(){
 const target=qs("#assocCompare");if(!target)return;
 if(!assocAlternative){target.innerHTML="";return;}
 const current=assocVersion,period=d.period,stage=d.stage,selected=assocResult?.totals;
 if(!selected){target.innerHTML='<span class="muted">Cargando contexto actual…</span>';return;}
 target.textContent="Consultando comparación…";
 try{const response=await gasGet("associations",{period,stage,assoc:JSON.stringify(assocAlternative)},false);
  if(!response.ok||current!==assocVersion||period!==d.period||stage!==d.stage)return;
  target.innerHTML='<strong>Contextos independientes</strong><span>A (fijado): Forecast '+money(response.totals.forecast)+' · Real '+money(response.totals.real)+'</span><span>B (activo): Forecast '+money(selected.forecast)+' · Real '+money(selected.real)+'</span><span>Δ Forecast '+signedMoney(selected.forecast-response.totals.forecast)+'</span><span class="muted">Misma etapa, mismo periodo y mismo alcance autorizado. PPTO/Año-1 solo comparables cuando su atribución se verifica.</span>';
 }catch(e){if(current===assocVersion)target.textContent="No se pudo comparar los contextos";}
}
function assocSelect_(dimension,value){
 if(!dimension||value===undefined||value===null||value==="")return;assocChange_(dimension,String(value),false);
}
function assocWorkbenchSelection_(){
 // Operational workbench values are never mutated by analytic selections.
 const host=qs("#content");if(!host)return;const enabled=assocActive_();
 const hint=host.querySelector(".assoc-workbench-note");if(hint)hint.remove();
 if(!enabled&&(!assocAnalyticPeriod||assocAnalyticPeriod===mesaOperationalPeriod))return;
 const hierarchy=enabled?assocWorkbenchHierarchy_(d.workbenchHierarchy):null;
 if(enabled&&!hierarchy)return; // Defer the selection count until the commercial hierarchy exists.
 const note=document.createElement("div");note.className="assoc-workbench-note panel";note.textContent=enabled?"Selecciones activas: visibles "+num(hierarchy.assocVisible)+" líneas de "+num((d.working||[]).length)+" autorizadas. El Forecast y las líneas ocultas permanecen intactos. Las dimensiones sin atribución verificable no eliminan importes.":"Mesa de Trabajo: el periodo operativo y los valores pendientes de guardar no cambian con filtros analíticos.";
 if(assocAnalyticPeriod&&assocAnalyticPeriod!==mesaOperationalPeriod){const msg=document.createElement("span");msg.textContent=" · Mesa operativa "+mesaOperationalPeriod+" · período analítico "+assocAnalyticPeriod+".";note.appendChild(msg);const adopt=document.createElement("button");adopt.type="button";adopt.className="action";adopt.textContent="Adoptar período analítico en Mesa";adopt.onclick=()=>{if(pendingWorking.size||wb2MissingEdits.size||autosaveInFlight)return showNotice("Guarda cambios antes de adoptar otro periodo");changeTopContext_(assocAnalyticPeriod,"");};note.appendChild(adopt);}
 host.prepend(note);
}

function signed(v){return (v>0?"+":"")+money(v)}
function money(v){return FMT_MONEY.format(num(v))}function num(v){const n=Number(v);return Number.isFinite(n)?n:0}function metric(x){if(!x||x.value==null)return esc(({NO_BUDGET:"Sin PPTO",NO_BASE:"Sin base",NO_FORECAST:"Sin forecast",NEW:"Nuevo"})[x?.kind]||"—");return FMT_DEC1.format(x.value)+"%"}function esc(v){return String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]))}function fail(m){qs("aside").style.display="none";qs("main").innerHTML='<div class="panel"><h1>Sfera</h1><p>'+esc(m)+'</p></div>'}boot();
